// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createLink, pinLink, getLink, deleteLink, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "name": "Skyramp Pin Invalid Id"
        },
        "name": "Skyramp Pin Invalid Id Link",
        "url": "https://example.com/skyramp-pin-invalid-id"
    }`;

    const linksPostResponse = await createLink(client, headers, linksPostRequestBody);

    expect(linksPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("Skyramp Pin Invalid Id Link");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/skyramp-pin-invalid-id");
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.collection.name"), 'collection name').toBe("Skyramp Pin Invalid Id");
    expect(getResponseValue(linksPostResponse, "response.id"), 'link id').toBeGreaterThan(0);

    const createdLinkId = getResponseValue(linksPostResponse, "response.id");
    const callerUserId = getResponseValue(linksPostResponse, "response.collection.ownerId");
    const createdCollectionId = getResponseValue(linksPostResponse, "response.collection.id");

    // Positive control: a well-formed link id is accepted and pins the link.
    const linksPinPatchResponse = await pinLink(client, headers, createdLinkId);

    expect(linksPinPatchResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksPinPatchResponse, "response.id"), 'pinned link id').toBe(createdLinkId);
    expect(getResponseValue(linksPinPatchResponse, "response.pinnedBy").length, 'pinnedBy holds exactly one pin after pinning').toBe(1);
    expect(getResponseValue(linksPinPatchResponse, "response.pinnedBy.0.id"), 'pinnedBy names the calling user').toBe(callerUserId);
    expect(getResponseValue(linksPinPatchResponse, "response.pinnedBy.1"), 'pinnedBy has no second entry').toBeNull();

    // A non-integer link id must be rejected, not truncated and applied to the link.
    const links53539PinPatchResponse = await pinLink(client, headers, `${createdLinkId}.9`, 400);

    expect(links53539PinPatchResponse.statusCode, 'status code').toBe(400);

    expect(getResponseValue(links53539PinPatchResponse, "response"), 'non-integer link id is refused with the endpoint\'s own message').toBe("Invalid link ID.");
    expect(getResponseValue(links53539PinPatchResponse, "response.pinnedBy"), 'a refused request returns no link payload').toBeNull();

    // A numeric link id that overflows to Infinity must be rejected, not crash the handler.
    const pinPatchResponse = await pinLink(client, headers, "1e400", 400);

    expect(pinPatchResponse.statusCode, 'status code').toBe(400);

    expect(getResponseValue(pinPatchResponse, "response"), 'overflowing numeric link id is refused with the endpoint\'s own message').toBe("Invalid link ID.");

    // A non-numeric link id is rejected.
    const abcPinPatchResponse = await pinLink(client, headers, "abc", 400);

    expect(abcPinPatchResponse.statusCode, 'status code').toBe(400);

    expect(getResponseValue(abcPinPatchResponse, "response"), 'non-numeric link id is refused').toBe("Invalid link ID.");

    // A link id that does not exist is rejected.
    const links999999999PinPatchResponse = await pinLink(client, headers, "999999999", 404);

    expect(links999999999PinPatchResponse.statusCode, 'status code').toBe(404);

    expect(getResponseValue(links999999999PinPatchResponse, "response"), 'unknown link id is refused').toBe("Link not found.");

    const linksLinksGetResponse = await getLink(client, headers, createdLinkId);

    expect(linksLinksGetResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksLinksGetResponse, "response.id"), 'link id').toBe(createdLinkId);
    expect(getResponseValue(linksLinksGetResponse, "response.name"), 'name is unchanged').toBe("Skyramp Pin Invalid Id Link");
    expect(getResponseValue(linksLinksGetResponse, "response.pinnedBy").length, 'the refused requests left the pin the positive control set').toBe(1);
    expect(getResponseValue(linksLinksGetResponse, "response.pinnedBy.0.id"), 'the surviving pin is the calling user\'s').toBe(callerUserId);
    expect(getResponseValue(linksLinksGetResponse, "response.pinnedBy.1"), 'pinnedBy has no second entry').toBeNull();

    const linksLinksDeleteResponse = await deleteLink(client, headers, createdLinkId);

    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted link id').toBe(createdLinkId);

    const collectionDeleteResponse = await deleteCollection(client, headers, createdCollectionId);

    expect(collectionDeleteResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(collectionDeleteResponse, "response.id"), 'deleted collection id').toBe(createdCollectionId);
});
